+import { createEventCard } from "./event-card.js";
+import { normalizeEmail } from "../lib/validation.js";
+
+export function buildInvitation(event, guest) {
+  const card = createEventCard(event);
+  const to = normalizeEmail(guest?.email);
+  return { to, subject: `Invitation: ${card.title}`, url: `/events/${card.id}` };
+}

