--- /dev/null
+++ b/src/features/agenda.js
@@ -0,0 +1,12 @@
+import { createEventCard } from "./event-card.js";
+
+export function sortByStartsAt(events) {
+  return events
+    .map((event, index) => ({ event, time: new Date(event.startsAt).getTime(), index }))
+    .sort((a, b) => a.time - b.time || a.index - b.index)
+    .map((entry) => entry.event);
+}
+
+export function buildAgenda(events) {
+  return sortByStartsAt(events).map(createEventCard);
+}

